import java.util.*;
import java.io.*;

public class Main {

    private static boolean contains(long[] a, long key) {
        int lo = 0, hi = a.length - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] == key) return true;
            if (a[mid] < key) lo = mid + 1;
            else hi = mid - 1;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line).append(' ');
        }
        StringTokenizer tok = new StringTokenizer(sb.toString());

        int n = Integer.parseInt(tok.nextToken());
        long[] pre = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) {
            total += Long.parseLong(tok.nextToken());
            pre[i] = total;
        }

        // Um retângulo inscrito num círculo tem diagonais que são diâmetros.
        // Logo, precisamos de pelo menos DOIS pares de árvores diametralmente
        // opostas (qualquer dois diâmetros distintos formam um retângulo).

        // Se a circunferência total for ímpar, não existe ponto oposto.
        if ((total & 1L) != 0) {
            System.out.println("N");
            return;
        }

        long half = total / 2;
        Arrays.sort(pre); // somas acumuladas (já ordenadas, por segurança)

        int count = 0; // conta extremidades de pares opostos
        for (int i = 0; i < n; i++) {
            long t = pre[i] + half;
            if (t >= total) t -= total;
            if (contains(pre, t)) count++;
        }

        // Cada par diametral é contado duas vezes; precisamos de >= 2 pares.
        System.out.println(count >= 4 ? "S" : "N");
    }
}
